from fractions import Fraction

def calculate_b_squared(x):
    # b^2 = x^2 + 4x + 3 - 2/x
    # Since x is an integer in the requested range, we can use fractions for exact arithmetic
    try:
        numerator = x*x + 4*x + 3 - 2
        denominator = x
        b_squared = Fraction(numerator, denominator)
        return b_squared
    except ZeroDivisionError:
        return None

x_values = [-3, -1, 1, 2, 3, 4]
results = {}

for x in x_values:
    b_sq = calculate_b_squared(x)
    if b_sq is not None:
        results[x] = b_sq

print("Calculated b^2 for integer x values:")
for x, b_sq in results.items():
    print(f"x={x} (a={x+2}): b^2 = {b_sq}")

